 printf("independent CRLF splits=%zu random_fragment_runs=200 passed\n",nc+1);json_set_alloc_funcs(fault_malloc,free);calls=0;fail_at=0;rc_response_observer *o=calloc(1,sizeof *o);assert(o);rc_response_observer_feed(o,wire,(size_t)n);calls=0;check(o);size_t total=calls;free(o);
 for(size_t i=1;i<=total;i++){o=calloc(1,sizeof *o);assert(o);fail_at=0;rc_response_observer_feed(o,wire,(size_t)n);calls=0;fail_at=i;fired=0;json_t *m=rc_response_observer_message(o);if(!fired||m){fprintf(stderr,"OOM failure index=%zu fired=%d accepted=%d\n",i,fired,m!=NULL);return 1;}json_decref(m);free(o);}
 fail_at=0;printf("independent CRLF splits=%zu random_fragment_runs=200 OOM_indices=%zu all passed\n",nc+1,total);
