#include "recursant/response_observer.h"
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char **argv) {
    int failed=0;
    for(int i=1;i<argc;i++) {
        FILE *f=fopen(argv[i],"rb"); if(!f)return 2;
        rc_response_observer *o=calloc(1,sizeof *o); if(!o)return 2;
        char b[37]; size_t n;
        while((n=fread(b,1,sizeof b,f)))rc_response_observer_feed(o,b,n);
        fclose(f); json_t *m=rc_response_observer_message(o);
        printf("wire_%d portable=%s observer_failed=%s\n",i,m?"true":"false",o->failed?"true":"false");
        if(!m)failed++;
        json_decref(m);free(o);
    }
    return failed?1:0;
}
